import json
from collections import defaultdict

ONTOLOGY_FILE = 'data/docred/ontology_constraints_docred.json'
with open(ONTOLOGY_FILE) as f:
    ontology = json.load(f)

ENTITY_TYPE_ALIASES = {
    'PERSON': 'PER', 'PEOPLE': 'PER',
    'ORGANIZATION': 'ORG', 'ORGANISATION': 'ORG',
    'LOCATION': 'LOC', 'NUMBER': 'NUM', 'NUMERICAL': 'NUM',
    'MISCELLANEOUS': 'MISC',
}
def normalize_etype(t):
    t_upper = t.strip().upper()
    if t_upper in ENTITY_TYPE_ALIASES:
        return ENTITY_TYPE_ALIASES[t_upper]
    return t.strip()

with open('outputs/w9_qwen_docred_zs_sampling_r3.jsonl') as f:
    lines = f.readlines()

examples = 0
for line in lines:
    doc = json.loads(line)
    parsed = doc.get('parsed_output')
    if not parsed:
        continue
    entity_types_map = defaultdict(set)
    for ent in parsed.get('entities', []):
        entity_types_map[ent.get('text', '')].add(normalize_etype(ent.get('type', '')))
    for rel in parsed.get('relations', []):
        entity_types_map[rel.get('head', '')].add(rel.get('head_type', ''))
        entity_types_map[rel.get('tail', '')].add(rel.get('tail_type', ''))
    conflicts = {k: v for k, v in entity_types_map.items() if len(v) > 1}
    if conflicts and examples < 5:
        examples += 1
        print(f'Doc: {doc[\"doc_id\"]}')
        for k, v in list(conflicts.items())[:3]:
            print(f'  \"{k}\" -> types: {v}')
        print()
"

